package com.ruoyi.system.service.impl;
import java.util.List; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import com.ruoyi.common.enums.DesensitizedType; import com.ruoyi.common.exception.ServiceException; import com.ruoyi.system.domain.shop.MallMember; import com.ruoyi.system.domain.shop.MallMemberAddress; import com.ruoyi.system.mapper.shop.MallMemberMapper; import com.ruoyi.system.service.IMallMemberService;
@Service public class MallMemberServiceImpl implements IMallMemberService { @Autowired private MallMemberMapper memberMapper; public List<MallMember> selectMemberList(MallMember m){List<MallMember> list=memberMapper.selectMemberList(m);for(MallMember i:list)i.setPhone(mask(i.getPhone()));return list;} public MallMember selectMemberById(Long id){MallMember m=memberMapper.selectMemberById(id);if(m!=null)m.setPhone(mask(m.getPhone()));return m;} public List<MallMemberAddress> selectAddresses(Long id){return memberMapper.selectAddressesByMemberId(id);} public int updateStatus(Long id,String status){if(!"0".equals(status)&&!"1".equals(status))throw new ServiceException("会员状态非法");MallMember m=new MallMember();m.setMemberId(id);m.setStatus(status);return memberMapper.updateMemberStatus(m);} private String mask(String phone){return phone==null?null:DesensitizedType.PHONE.desensitizer().apply(phone);} }
